from pathlib import Path
def read(path):
    return Path(path).read_text(encoding="utf-8")

def write(path, text):
    Path(path).write_text(text, encoding="utf-8", newline="\n")

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one match, got {count}")
    return text.replace(old, new, 1)

p = Path("src/Constants.h")
t = read(p)
t = replace_once(t, '#define SEQ_MAX_STEPS 256', '#define SEQ_MAX_STEPS 1024', "SEQ_MAX_STEPS")
if "#define SEQ_MAX_STEPS_PER_MEASURE" not in t:
    t = replace_once(t, '#define SEQ_DEFAULT_NUM_STEPS 16', '#define SEQ_DEFAULT_NUM_STEPS 16\n#define SEQ_MAX_STEPS_PER_MEASURE 32', "steps-per-measure constant")
write(p, t)

p = Path("src/SequenceData.h")
t = read(p)
if "#include <cstdint>" not in t:
    anchor = '#include "Scale.h"'
    if anchor in t:
        t = t.replace(anchor, anchor + "\n#include <cstdint>", 1)
    else:
        t = "#include <cstdint>\n" + t
t = replace_once(t, 'unsigned char col;', 'uint16_t col;', "SourceCell col")
write(p,t)

p = Path("src/SequenceData.cpp")
