t = replace_once(t, 'third = (len << 8) + pos;', 'third = ((len & 0xFFFF) << 16) | (pos & 0xFFFF);', 'completed-note pack')
t = replace_once(t, '*pos = third & 0xFF;\n      *len = third >> 8;', '*pos = third & 0xFFFF;\n      *len = (third >> 16) & 0xFFFF;', 'completed-note unpack')
t = replace_once(t, 'cells[i].col == (unsigned char)sourceStep &&', 'cells[i].col == static_cast<uint16_t>(sourceStep) &&', 'chain compare')
t = replace_once(t, 'cells[availableCell].col = (unsigned char)sourceStep;', 'cells[availableCell].col = static_cast<uint16_t>(sourceStep);', 'chain assign')
t = replace_once(t, 'jassert(val >= SEQ_MIN_STEPS && val <= SEQ_DEFAULT_NUM_STEPS);\n   mStepsPerMeasure = val;', 'jassert(val >= SEQ_MIN_STEPS && val <= SEQ_MAX_STEPS_PER_MEASURE);\n   mStepsPerMeasure = val;', 'steps-per-measure assert')
write(p,t)

